220	// An exception that matches nothing is stale, and so is an entry point that no
221	// longer builds the run: the guard would pass with nothing left to guard.
222	func TestContainerGuardEveryExceptionStillMatches(t *testing.T) {
223		_, vs := scanContainerRepo(t)
224		if !slices.ContainsFunc(vs, isContainerEntryPoint) {
225			t.Errorf("%s no longer builds a run in %s; the entry point moved, update containerRunFile/containerRunFunc and the doc", containerRunFunc, containerRunFile)
226		}
227		seen := map[exception]bool{}
228		for _, e := range containerExceptions {
229			key := exception{File: e.File, Func: e.Func, Rule: e.Rule}
230			if seen[key] {
231				t.Errorf("exception %s %s %s is listed twice", e.File, e.Func, e.Rule)
232			}
233			seen[key] = true
234			if !slices.Contains(containerRules, e.Rule) {
235				t.Errorf("exception %s %s: rule %q is not one of %v", e.File, e.Func, e.Rule, containerRules)
236			}
237			if strings.TrimSpace(e.Why) == "" || strings.TrimSpace(e.Until) == "" {
238				t.Errorf("exception %s %s %s needs a reason and an end (\"permanent\" or a story)", e.File, e.Func, e.Rule)
239			}
240			if !slices.ContainsFunc(vs, e.covers) {
241				t.Errorf("stale exception: %s %s %s matches no container launch any more; remove it from containerExceptions and docs/architecture/network.md", e.File, e.Func, e.Rule)
242			}
243		}
244	}
