302			CacheDir:          KubeconformCacheDir(),
303			AllowRemoteBases:  s.options.Tools.Kustomize.AllowRemoteBases,
304		}
305		// A renderer serves only when it is ticked: installed and unticked, it is
306		// not used (§3.86), and its charts or overlays are reported as not rendered.
307		if s.runs(CategoryIDMisconfig, ToolHelm, TargetDirectory) {
308			opts.Helm = s.spec(ToolHelm)
309		}
310		if s.runs(CategoryIDMisconfig, ToolKustomize, TargetDirectory) {
311			opts.Kustomize = s.spec(ToolKustomize)
312		}
313		return opts
314	}
