316	// runKubeconformStage is the schema stage of Scan, shaped like the others:
317	// progress, then findings or a stage error under the result's lock.
318	func (s *Scanner) runKubeconformStage(ctx context.Context, target string, result *Result, mu *sync.Mutex, notify func(ProgressUpdate)) {
319		const stage, label = "k8s-schema", "Kubernetes schema"
320		notify(ProgressUpdate{Stage: stage, Label: label, Status: StageRunning})
321		progressFn := func(detail string) {
322			notify(ProgressUpdate{Stage: stage, Label: label, Status: StageRunning, Detail: detail})
323		}
324		report, err := RunKubeconform(ctx, target, s.spec(ToolKubeconform), s.kubeconformOptions(), progressFn)
325	
326		mu.Lock()
327		defer mu.Unlock()
328		if err != nil {
329			recordStageError(result, "kubeconform", err)
330			notify(ProgressUpdate{Stage: stage, Label: label, Status: StageError, Detail: err.Error()})
331			return
332		}
333		if report.SkippedCustom > 0 {
334			log.Printf("[scan/kubeconform] %s: %d custom resources not validated (their schema is in a CRD)", target, report.SkippedCustom)
335		}
336		if len(report.Unrendered) > 0 {
337			log.Printf("[scan/kubeconform] %s: not rendered, so not validated: %s", target, strings.Join(report.Unrendered, ", "))
338		}
339		result.K8sUnrendered = report.Unrendered
340		result.Findings = append(result.Findings, report.Findings...)
341		// Schema validation is the second half of the Misconfiguration category, so
342		// a run of it makes the verdict known on its own: a repository scanned with
343		// Trivy's rules switched off but kubeconform on has been looked at, and a
344		// "-" there would say otherwise. What the stage could not render is carried
345		// in K8sUnrendered and comes back out as the column's "?".
346		result.MisconfigScanned = true
347		notify(ProgressUpdate{Stage: stage, Label: label, Status: StageDone})
348	}
