49	// annotateSeccompContext sets SeccompOrigin on the kubernetes KSV-0104 findings
50	// of a directory scan, reading and decoding each file once however many
51	// findings point into it. It never fails the scan: whatever it cannot confirm
52	// leaves the origin empty, which reads as "unknown". It stops between files
53	// once ctx is done.
54	func annotateSeccompContext(ctx context.Context, root string, findings []Finding) {
55		byFile := map[string][]int{}
56		for i, f := range findings {
57			if f.Source == SourceTrivyMisconfig && f.IaCType == "kubernetes" && isSeccompRule(f.ID) {
58				byFile[f.File] = append(byFile[f.File], i)
59			}
60		}
61		if len(byFile) == 0 {
62			return
63		}
64		dir, err := os.OpenRoot(root)
65		if err != nil {
66			log.Printf("WARN [scan] seccomp origin: cannot open %s: %v", root, err)
67			return
68		}
69		defer func() { _ = dir.Close() }()
70	
71		for file, indexes := range byFile {
72			if ctx.Err() != nil {
73				return
74			}
75			name := filepath.FromSlash(file)
76			if !filepath.IsLocal(name) {
77				log.Printf("WARN [scan] seccomp origin: %s is outside the scanned directory", file)
78				continue
79			}
80			content, err := k8s.ReadManifestIn(dir, name)
81			if err != nil {
82				log.Printf("WARN [scan] seccomp origin: cannot read %s: %v", file, err)
83				continue
84			}
85			documents := indexDocuments(content)
86			for _, i := range indexes {
87				if ctx.Err() != nil {
88					return
89				}
90				findings[i].SeccompOrigin = seccompOriginIn(documents, findings[i])
91			}
92		}
93	}
