94	// CheckBuildContext returns what the root Dockerfiles of root would copy into
95	// their image that should not be there.
96	func CheckBuildContext(root string) ([]Finding, error) {
97		entries, err := os.ReadDir(root)
98		if errors.Is(err, fs.ErrNotExist) {
99			// Nothing to read, and the scanners that were asked to read it say so
100			// themselves: one missing directory is one error, not one per stage.
101			return nil, nil
102		}
103		if err != nil {
104			return nil, err
105		}
106		hasGit := false
107		if info, err := os.Stat(filepath.Join(root, ".git")); err == nil && info.IsDir() {
108			// A worktree's .git is a file naming the real one elsewhere: copying it
109			// exposes a path, not a history.
110			hasGit = true
111		}
112		var candidates []string // walked once, only if a Dockerfile needs it
113		walked := false
114	
115		var findings []Finding
116		for _, e := range entries {
117			if !e.Type().IsRegular() || !dockerfile.IsDockerfileName(e.Name()) {
118				continue
119			}
120			cp, ok, err := wholeContextCopy(filepath.Join(root, e.Name()))
121			if err != nil {
122				log.Printf("ERROR [scan/build-context] read %s: %v", e.Name(), err)
123				continue
124			}
125			if !ok {
126				continue
127			}
128			sent, ok := contextFilter(root, e.Name())
129			if !ok {
130				continue
131			}
132			if hasGit && sent(".git", true) {
133				findings = append(findings, gitFinding(root, e.Name(), cp))
134			}
135			if !walked {
136				candidates, walked = sensitiveCandidates(root), true
137			}
138			var exposed []string
139			for _, c := range candidates {
140				if sent(c, false) {
141					exposed = append(exposed, c)
142				}
143			}
144			if len(exposed) > 0 {
145				findings = append(findings, sensitiveFinding(e.Name(), cp, exposed))
