152	// wholeContextCopy returns the first COPY or ADD of the file that takes the
153	// whole context in a stage the final image is built from.
154	//
155	// An earlier stage's layers are not the image's: a builder stage that copies
156	// everything and hands one binary to the next exposes nothing. A final stage
157	// built FROM an earlier one carries that stage's layers, so the chain is
158	// followed. A `COPY --from` of a whole earlier stage is left alone — what it
159	// carries depends on that stage's paths, which is a guess.
160	func wholeContextCopy(path string) (dockerfile.Copy, bool, error) {
161		content, err := os.ReadFile(path) //nolint:gosec // a Dockerfile of the directory being scanned
162		if err != nil {
163			return dockerfile.Copy{}, false, err
164		}
165		stages := dockerfile.Parse(content).Stages
166		var best dockerfile.Copy
167		found := false
168		for _, st := range shippedStages(stages) {
169			for _, cp := range st.Copies {
170				if cp.TakesWholeContext() && (!found || cp.Line < best.Line) {
171					best, found = cp, true
172				}
173			}
174		}
175		return best, found, nil
176	}
