178	// shippedStages are the final stage and the earlier stages it is built FROM.
179	func shippedStages(stages []dockerfile.Stage) []dockerfile.Stage {
180		if len(stages) == 0 {
181			return nil
182		}
183		i := len(stages) - 1
184		out := []dockerfile.Stage{stages[i]}
185		for stages[i].Kind == dockerfile.KindStage {
186			parent := -1
187			for j := i - 1; j >= 0; j-- {
188				if strings.EqualFold(stages[j].Name, stages[i].Written) {
189					parent = j
190					break
191				}
192			}
193			if parent < 0 {
194				break
195			}
196			i = parent
197			out = append(out, stages[i])
198		}
199		return out
200	}
