202	// contextFilter returns whether a path is certainly sent to the builder of the
203	// Dockerfile at root/name: no ignore file that may apply leaves it out, and
204	// every one of them can be read with certainty. ok is false when an ignore file
205	// cannot be read at all, which leaves the Dockerfile unchecked.
206	func contextFilter(root, name string) (sent func(rel string, tree bool) bool, ok bool) {
207		var ignores []dockerfile.Ignore
208		for _, rel := range dockerfile.IgnoreFiles(root, name) {
209			content, err := os.ReadFile(filepath.Join(root, filepath.FromSlash(rel))) //nolint:gosec // an ignore file of the directory being scanned
210			if err != nil {
211				log.Printf("ERROR [scan/build-context] read %s: %v", rel, err)
212				return nil, false
213			}
214			ignores = append(ignores, dockerfile.ParseIgnore(content))
215		}
216		return func(rel string, tree bool) bool {
217			for _, ig := range ignores {
218				excluded, certain := ig.Excluded(rel)
219				if tree {
220					excluded, certain = ig.ExcludesTree(rel)
221				}
222				if excluded || !certain {
223					return false
224				}
225			}
226			return true
227		}, true
228	}
