230	// sensitiveCandidates lists the sensitive files under root, as slash paths
231	// relative to it, whatever the ignore files say — that is decided per
232	// Dockerfile.
233	func sensitiveCandidates(root string) []string {
234		var out []string
235		_ = filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
236			if err != nil {
237				return nil // an unreadable subdirectory is skipped, not fatal
238			}
239			rel, relErr := filepath.Rel(root, path)
240			if relErr != nil || rel == "." {
241				return nil
242			}
243			if d.IsDir() {
244				if contextSkippedDirs[d.Name()] || strings.Count(rel, string(filepath.Separator)) >= maxContextDepth {
245					return filepath.SkipDir
246				}
247				return nil
248			}
249			if d.Type().IsRegular() && isSensitiveName(d.Name()) {
250				out = append(out, filepath.ToSlash(rel))
251			}
252			if len(out) >= maxContextSensitive {
253				return filepath.SkipAll
254			}
255			return nil
256		})
257		sort.Strings(out)
258		return out
259	}
