118			// directory is one error, not one per stage — build-context's rule.
119			return nil, nil
120		}
121		if err != nil {
122			return nil, []error{err}
123		}
124		verdicts := map[string]trust.Result{}
125		reported := map[string]bool{}
126		var findings []Finding
127		var errs []error
128		for _, rel := range files {
129			content, err := os.ReadFile(filepath.Join(target, filepath.FromSlash(rel))) //nolint:gosec // a Dockerfile of the directory being scanned
130			if err != nil {
