132				continue
133			}
134			for _, st := range dockerfile.Parse(content).Stages {
135				if st.Kind != dockerfile.KindImage || st.Image == "" {
136					continue
137				}
138				res, seen := verdicts[st.Image]
139				if !seen {
140					res, _ = trust.Check(ctx, st.Image, "", deps)
141					verdicts[st.Image] = res
142				}
143				if f, ok := signatureFinding(rel, st, res); ok {
144					findings = append(findings, f)
145				} else if res.Decision == trust.Block && (res.Verdict == trust.Failed || !res.Proven()) && !reported[st.Image] {
