147					// whose answer was inferred from a failure: said once per
148					// image, as the stage's error, not as a fact.
149					reported[st.Image] = true
150					errs = append(errs, fmt.Errorf("%s: %s", st.Image, res.Reason()))
151				}
152			}
153		}
154		return findings, errs
155	}
